import { createContext, useContext } from "react";

type TableKeyboardNavContextType = {
  enableKeyboardShortcuts?: boolean;
  handleKeyDown?: (e: React.KeyboardEvent<HTMLElement>) => void;
};

export const TableKeyboardNavContext = createContext<TableKeyboardNavContextType | undefined>(
  undefined,
);

export const useTableKeyboardNavContext = () => {
  const context = useContext(TableKeyboardNavContext);
  if (!context) {
    throw new Error("useTableKeyboardNavContext must be used within a TableKeyboardNavProvider");
  }
  return context;
};
